class Solution {
    public long biggestTank(int[] posts) {
        long best = 0;
        for (int i = 0; i < posts.length; i++)
            for (int j = i + 1; j < posts.length; j++)
                best = Math.max(best, (long) (j - i) * Math.min(posts[i], posts[j]));
        return best;
    }
}

