long long biggestTank(int* posts, int postsSize) {
    long long best = 0;
    for (int i = 0; i < postsSize; i++)
        for (int j = i + 1; j < postsSize; j++) {
            int h = posts[i] < posts[j] ? posts[i] : posts[j];
            if ((long long) (j - i) * h > best) best = (long long) (j - i) * h;
        }
    return best;
}

