class Solution:
    def biggestTank(self, posts: List[int]) -> int:
        i, j, best = 0, len(posts) - 1, 0
        while i < j:
            best = max(best, (j - i) * min(posts[i], posts[j]))
            if posts[i] < posts[j]:
                i += 1
            else:
                j -= 1
        return best

