class Solution {
    public long biggestTank(int[] posts) {
        int i = 0, j = posts.length - 1;
        long best = 0;
        while (i < j) {
            best = Math.max(best, (long) (j - i) * Math.min(posts[i], posts[j]));
            if (posts[i] < posts[j]) i++;
            else j--;
        }
        return best;
    }
}

